/*
 * A042319  Denominators of continued fraction convergents to sqrt(686).
 * https://oeis.org/A042319
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) = denominator of the n‑th convergent of sqrt(686)
 * Range:     u8 n <= 5, u16 n <= 7, u32 n <= 15, u64 n <= 31, u128 n <= 61,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The continued fraction coefficients a_k (k ≥ 1) are generated by:
       m_{k+1} = d_k * a_k – m_k
       d_{k+1} = (686 – m_{k+1}^2) / d_k
       a_{k+1} = floor((a₀ + m_{k+1}) / d_{k+1})   with a₀ = 26.
   The denominators Q_k satisfy Q_{-1}=0, Q_0=1 and
       Q_k = a_k * Q_{k-1} + Q_{k-2}.  This function returns Q_n for any n ≥ 0. */

seq_t a(idx_t n)
{
    /* Handle the offset explicitly. */
    if (n == 0)
        return (seq_t)1;          /* Q_0 = 1 */

    /* Initial values for the continued fraction of sqrt(686). */
    const idx_t a0 = 26;           /* floor(sqrt(686)) */
    idx_t m = 0;
    idx_t d = 1;
    idx_t a_curr = a0;             /* a_0 */

    /* Denominator recurrence Q_{-1}=0, Q_0=1 */
    seq_t Q_prev2 = (seq_t)0;      /* Q_{-1} */
    seq_t Q_prev1 = (seq_t)1;      /* Q_0   */

    for (idx_t i = 1; i <= n; ++i)
    {
        /* Compute next continued fraction coefficient a_next. */
        idx_t m_next = d * a_curr - m;
        idx_t d_next = (686 - m_next * m_next) / d;
        idx_t a_next = (a0 + m_next) / d_next;

        /* Update denominators: Q_i = a_next * Q_{i-1} + Q_{i-2}. */
        seq_t Q_curr = ((seq_t)a_next) * Q_prev1 + Q_prev2;

        /* Shift for next iteration. */
        Q_prev2 = Q_prev1;
        Q_prev1 = Q_curr;

        /* Advance to the next coefficient. */
        m = m_next;
        d = d_next;
        a_curr = a_next;
    }

    return Q_prev1;
}
